  </tr></thead><tbody class="divide-y divide-slate-100 dark:divide-slate-800">
  <?php $no=$offset+1; foreach($transfers as $trf):
    $sumStmt=$pdoView->prepare("SELECT COUNT(*) AS item_types, COALESCE(SUM(quantity_sent),0) AS qty_sent, COALESCE(SUM(quantity_received),0) AS qty_received, SUM(CASE WHEN m.is_serialized=1 THEN 1 ELSE 0 END) AS serialized_types FROM transfer_items ti JOIN master_items m ON m.id=ti.master_item_id WHERE ti.transfer_id=?");
    $sumStmt->execute([(int)$trf['id']]); $summary=$sumStmt->fetch(PDO::FETCH_ASSOC) ?: ['item_types'=>0,'qty_sent'=>0,'qty_received'=>0,'serialized_types'=>0];
    $sent=(int)$summary['qty_sent']; $received=(int)$summary['qty_received']; $progress=$sent>0?min(100,round(($received/$sent)*100)):0;
    $photoStmt=$pdoView->prepare("SELECT COUNT(*) FROM attachments WHERE reference_id=? AND reference_type IN ('transfer_dispatch','transfer_receive')"); $photoStmt->execute([(int)$trf['id']]); $photoCount=(int)$photoStmt->fetchColumn();
    $badgeType=$trf['status']==='IN_TRANSIT'?'INFO':($trf['status']==='COMPLETED'?'SUCCESS':'WARNING');
  ?>
  <tr class="transition-colors hover:bg-slate-50/80 dark:hover:bg-slate-800/40">
    <td class="px-4 py-3.5 text-center text-xs text-slate-400 font-semibold"><?= $no++ ?></td>
    <td class="px-4 py-3.5"><div class="font-bold text-sm text-slate-900 dark:text-slate-100"><?= htmlspecialchars($trf['transaction_code']) ?></div><div class="mt-0.5 text-xs text-slate-400"><?= date('d M Y, H:i',strtotime($trf['sent_at'])) ?></div></td>
    <td class="px-4 py-3.5"><div class="text-sm font-semibold text-slate-800 dark:text-slate-200"><?= htmlspecialchars($trf['source_warehouse']) ?></div><div class="my-0.5 text-xs text-slate-400">↓</div><div class="text-sm font-semibold text-blue-600 dark:text-blue-400"><?= htmlspecialchars($trf['dest_warehouse']) ?></div></td>
    <td class="px-4 py-3.5"><div class="flex flex-wrap gap-1.5"><span class="rounded-full bg-blue-50 px-2.5 py-0.5 text-[11px] font-semibold text-blue-700 dark:bg-blue-950/40 dark:text-blue-300"><?= (int)$summary['item_types'] ?> jenis</span><span class="rounded-full bg-slate-100 px-2.5 py-0.5 text-[11px] font-semibold text-slate-700 dark:bg-slate-800 dark:text-slate-200"><?= number_format($sent) ?> unit</span><?php if((int)$summary['serialized_types']>0): ?><span class="rounded-full bg-purple-50 px-2.5 py-0.5 text-[11px] font-semibold text-purple-700 dark:bg-purple-950/40 dark:text-purple-300"><i class="fas fa-barcode mr-1"></i> Serial</span><?php endif; ?></div><div class="mt-1 text-xs text-slate-400">Diterima <?= number_format($received) ?> / <?= number_format($sent) ?></div></td>
    <td class="px-4 py-3.5"><div class="text-sm font-medium text-slate-800 dark:text-slate-200"><?= htmlspecialchars($trf['sender_name']) ?></div><div class="mt-1.5 flex items-center gap-2"><div class="h-1.5 w-24 overflow-hidden rounded-full bg-slate-100 dark:bg-slate-800"><div class="h-full rounded-full bg-blue-600" style="width:<?= $progress ?>%"></div></div><span class="text-xs font-semibold text-slate-400"><?= $progress ?>%</span></div><div class="mt-0.5 text-xs text-slate-400"><i class="fas fa-camera mr-1"></i><?= $photoCount ?> bukti</div></td>
    <td class="px-4 py-3.5"><?= \App\Helpers\UIHelper::badge($trf['status'],$badgeType) ?><div class="mt-0.5 text-xs text-slate-400"><?= $trf['status']==='COMPLETED' ? 'Barang sudah diterima' : ($trf['status']==='PARTIAL_RECEIVED' ? 'Diterima sebagian' : 'Dalam perjalanan') ?></div></td>
    <td class="px-4 py-3.5"><div class="flex items-center justify-center gap-1.5"><a href="<?= url('/transfers/show?id='.(int)$trf['id']) ?>" class="inline-flex items-center gap-1 rounded-xl border border-slate-200 bg-white px-2.5 py-1.5 text-xs font-semibold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-200 dark:hover:bg-slate-700"><i class="fas fa-eye text-[10px]"></i> Detail</a><a href="<?= url('/transfers/documents?id='.(int)$trf['id']) ?>" class="inline-flex items-center gap-1 rounded-xl border border-blue-200 bg-blue-50 px-2.5 py-1.5 text-xs font-semibold text-blue-700 hover:bg-blue-100 dark:border-blue-900/60 dark:bg-blue-950/30 dark:text-blue-300"><i class="fas fa-file-lines text-[10px]"></i> Surat Jalan</a><?php if ($trf['status']==='IN_TRANSIT' && \App\Helpers\AuthHelper::hasRole('ADMIN')): ?><form action="<?= url('/transfers/delete') ?>" method="POST" class="inline"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><input type="hidden" name="id" value="<?= (int)$trf['id'] ?>"><button type="submit" class="inline-flex items-center p-1.5 rounded-xl border border-red-200 bg-white text-red-600 hover:bg-red-50 dark:border-red-900/60 dark:bg-slate-800 dark:text-red-300" data-confirm="Transfer ini akan dibatalkan dan stok dikembalikan ke gudang asal. Lanjutkan?" data-confirm-title="Hapus Transfer" data-confirm-type="danger" data-confirm-icon="fa-trash" data-confirm-confirm="Hapus" data-confirm-loading="Menghapus..."><i class="fas fa-trash text-xs"></i></button></form><?php endif; ?></div></td>
  </tr>
  <?php endforeach; ?>
